<script setup lang="ts">
import {ref,onMounted,computed} from 'vue'
import {useRouter} from 'vue-router'
import {ElMessage} from 'element-plus'
import {api,errorMessage,user,download} from '../api/http'
const router=useRouter(),canUpload=computed(()=>user.value?.roles.includes('ROLE_ADMIN'))
const selected=ref<File|null>(null),preview=ref<any>(null),busy=ref(false),ack=ref(false),result=ref<any>(null),history=ref<any[]>([]),historyTotal=ref(0),historyPage=ref(1),historyBusy=ref(false),details=ref<any>(null),logs=ref<any[]|null>(null)
function choose(e:Event){selected.value=(e.target as HTMLInputElement).files?.[0]||null;preview.value=null;ack.value=false;result.value=null}
async function parse(){if(!selected.value||busy.value)return;busy.value=true;preview.value=null;ack.value=false;result.value=null;try{const form=new FormData();form.append('file',selected.value);preview.value=await api('/imports/deadlines/preview',{method:'POST',body:form})}catch(e){ElMessage.error(errorMessage(e))}finally{busy.value=false}}
async function save(){if(!selected.value||!preview.value||!ack.value||busy.value)return;busy.value=true;try{const form=new FormData();form.append('file',selected.value);form.append('previewToken',preview.value.previewToken);form.append('acknowledgeReview','true');form.append('decisions',JSON.stringify(Object.fromEntries(preview.value.rows.map((r:any)=>[r.data.sourceRow,r.action]))));result.value=await api('/imports/deadlines',{method:'POST',body:form});preview.value=null;ack.value=false;ElMessage.success('取込み結果を保存しました');historyPage.value=1;await loadHistory()}catch(e){ElMessage.error(errorMessage(e))}finally{busy.value=false}}
async function loadHistory(){historyBusy.value=true;try{const d=await api<any>('/imports/deadlines/history?page='+(historyPage.value-1));history.value=d.rows;historyTotal.value=d.total}catch(e){ElMessage.error(errorMessage(e))}finally{historyBusy.value=false}}
async function file(row:any){try{await download('/imports/deadlines/'+row.import_id+'/file',row.file_name)}catch(e){ElMessage.error(errorMessage(e))}}
async function showLogs(row:any){try{logs.value=await api<any[]>('/imports/deadlines/'+row.import_id+'/rows')}catch(e){ElMessage.error(errorMessage(e))}}
onMounted(loadHistory)
</script>
<template>
<div class="banner">「期限管理表」シートを取込み、販売管理と5年間監視で共用します。年度の期限・予定日・完了日・原文を分けて保存し、監視状態は自動判定しません。</div>
<div class="actions" style="margin-bottom:18px"><el-button @click="router.push('/sales')">販売管理で検索</el-button><el-button @click="router.push('/monitor')">5年間監視で検索</el-button></div>
<section v-if="canUpload" class="panel"><header class="panel-heading">期限管理表の取込み</header><div class="panel-body"><p>Excelを選択 → プレビューと各行の処理を確認 → 確定保存</p><input aria-label="期限管理表Excel" type="file" accept=".xlsx,.xls" :disabled="busy" @change="choose"/><el-button type="primary" :disabled="!selected" :loading="busy" @click="parse" style="margin-left:12px">プレビュー</el-button>
<template v-if="preview"><p>解析 {{preview.recordCount}} 件 · 新規 {{preview.newCount}} 件 · 既存 {{preview.existingCount}} 件 · エラー {{preview.errorCount}} 件</p><el-alert v-if="preview.alreadyImported" title="同一ファイルの取込み履歴があります。既存記録はスキップが初期値です。更新する場合は明示的に選択してください。" type="info" :closable="false"/>
<el-table :data="preview.rows" border><el-table-column label="Excel行" width="90"><template #default="s">{{s.row.data.sourceRow}}〜{{s.row.data.endRow}}</template></el-table-column><el-table-column prop="data.contractNo" label="契約番号" width="120"/><el-table-column prop="data.productName" label="商品名" min-width="220"/><el-table-column prop="data.modelNo" label="型番" min-width="170"/><el-table-column label="確認" width="130"><template #default="s"><el-button size="small" @click="details=s.row">{{s.row.invalid?'エラー':s.row.data.warnings.length?'要確認':'詳細'}}</el-button></template></el-table-column><el-table-column label="取込方法" width="150"><template #default="s"><el-select v-model="s.row.action" :disabled="busy||s.row.invalid"><el-option v-if="!s.row.existingId" label="新規追加" value="ADD"/><el-option v-if="s.row.existingId" label="原資料を更新" value="UPDATE"/><el-option label="スキップ" value="SKIP"/></el-select></template></el-table-column></el-table>
<p class="data-note">照合は契約・商品・型番・許可番号の組合せです。既存は初期値スキップ。更新は元資料の項目のみで、システム側の手動監視状態・日付・メモを上書きしません。照合項目自体が変わった場合は新規候補になるため、詳細を確認してください。</p>
<el-checkbox v-model="ack" :disabled="busy">要確認事項・重複候補・各行の処理を確認しました</el-checkbox><el-button type="primary" :disabled="!ack" :loading="busy" @click="save" style="margin-left:12px">確認して保存</el-button></template>
<el-alert v-if="result" :title="`取込み結果：追加 ${result.added}、更新 ${result.updated}、スキップ ${result.skipped}、エラー ${result.failed} 件${result.duplicate?'（同一ファイル）':''}`" type="success" :closable="false" style="margin-top:16px"/></div></section>
<el-alert v-else title="取込みは管理者のみ実行できます。保存済み記録は検索できます。" type="info" :closable="false"/>
<section class="panel"><header class="panel-heading">期限管理表の取込み履歴</header><div class="panel-body"><el-table :data="history" v-loading="historyBusy" border><el-table-column prop="file_name" label="元ファイル" min-width="220"/><el-table-column prop="created_at" label="取込日時" min-width="190"/><el-table-column prop="added_count" label="追加" width="65"/><el-table-column prop="updated_count" label="更新" width="65"/><el-table-column prop="skipped_count" label="スキップ" width="85"/><el-table-column prop="failed_count" label="エラー" width="75"/><el-table-column label="操作" width="180"><template #default="s"><el-button size="small" @click="file(s.row)">元ファイル</el-button><el-button size="small" @click="showLogs(s.row)">ログ</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="historyPage" :total="historyTotal" :page-size="20" layout="total,prev,pager,next" @current-change="loadHistory"/></div></section>
<el-dialog :model-value="!!details" title="解析結果・原文" width="85%" @close="details=null"><template v-if="details"><el-alert v-if="details.conflict" title="同じ照合情報がファイル内に複数あります。自動統合せずエラー扱いにします。" type="error" :closable="false"/><el-alert v-for="(e,i) in details.data.errors" :key="'e'+i" :title="e" type="error" :closable="false"/><el-alert v-for="(w,i) in details.data.warnings" :key="i" :title="w" type="warning" :closable="false"/><el-descriptions :column="2" border style="margin:16px 0"><el-descriptions-item label="契約番号">{{details.data.contractNo}}</el-descriptions-item><el-descriptions-item label="許可日">{{details.data.permitDate||'要確認'}}</el-descriptions-item><el-descriptions-item label="有効期限">{{details.data.validUntil||'要確認'}}</el-descriptions-item><el-descriptions-item label="報告期限">{{details.data.reportDueDate||'要確認'}}</el-descriptions-item></el-descriptions><el-table :data="details.data.years" border><el-table-column prop="year" label="年度" width="65"/><el-table-column prop="dueDate" label="原票の期限"/><el-table-column prop="plannedDate" label="予定日（明記分）"/><el-table-column prop="completedDate" label="完了日（明記分）"/><el-table-column label="原文" min-width="250"><template #default="s"><div style="white-space:pre-wrap">{{s.row.rawText}}</div></template></el-table-column></el-table><el-collapse><el-collapse-item title="全項目・元セル・条件内容"><pre class="raw-json">{{JSON.stringify(details.data,null,2)}}</pre></el-collapse-item></el-collapse></template></el-dialog>
<el-dialog :model-value="logs!==null" title="行別取込み履歴" width="80%" @close="logs=null"><el-table :data="logs||[]" border><el-table-column prop="source_row" label="Excel行"/><el-table-column prop="action" label="処理"/><el-table-column label="契約番号"><template #default="s">{{JSON.parse(s.row.source_data).contractNo}}</template></el-table-column><el-table-column label="エラー"><template #default="s">{{JSON.parse(s.row.source_data).errors.join('、')}}</template></el-table-column></el-table></el-dialog>
</template>
<style scoped>.raw-json{white-space:pre-wrap;overflow-wrap:anywhere;max-height:400px;overflow:auto}</style>
